// Initial file generated by Claude Sonnet 5.5

import { beforeEach, describe, expect, it, vi } from "vitest";

import type { Gallery     } from "@/core/Gallery.ts";
import { uploadNewGallery } from "@/core/uploadNewGallery.ts";


const authorizedFetch = vi.hoisted(() => vi.fn());

vi.mock("@/core/TeacherAuth.ts", () => ({ authorizedFetch }));

const NANO = "V1StGXR8_Z5jdHi6B-myT";

async function lastForm(): Promise<FormData> {
  const options = authorizedFetch.mock.calls.at(-1)![1] as { body: FormData };
  return options.body;
}

describe("uploadNewGallery", () => {

  beforeEach(() => { authorizedFetch.mockReset(); });

  it("POSTs the form fields the server's /new-session handler requires", async () => {
    authorizedFetch.mockResolvedValue(new Response(NANO, { status: 200 }));
    await uploadNewGallery("Period 3", "netsblox", true, "Describe it", "starter-xml");

    expect(authorizedFetch.mock.calls[0]![0]).toBe("/api/galleries/teacher/new-session");
    const form = await lastForm();
    expect(form.get("gallery-name")).toBe("Period 3");
    expect(form.get("template")).toBe("netsblox");
    expect(form.get("gets-prescreened")).toBe("true");
    expect(form.get("description")).toBe("Describe it");
    expect(form.has("config")).toBe(true);
  });

  it("returns a Success carrying a fresh, empty gallery that uses the server-issued ID", async () => {
    authorizedFetch.mockResolvedValue(new Response(NANO, { status: 200 }));
    const result = await uploadNewGallery("Period 3", "netsblox", false, "d", "");

    expect(result.isOK).toBe(true);
    const gallery = result.fold(() => { throw new Error("expected success"); }, (g: Gallery) => g);
    expect(gallery).toMatchObject({ id: NANO, numApproved: 0, numWaiting: 0, lastSubTime: null, isPrescreened: false });
  });

  it("returns a Failure carrying the server's message when the request is rejected", async () => {
    authorizedFetch.mockResolvedValue(new Response("Something just like that already exists.", { status: 409 }));
    const result = await uploadNewGallery("Dupe", "demo", false, "", "");

    expect(result.isOK).toBe(false);
    const message = result.fold((e: Error) => e.message, () => "");
    expect(message).toBe("Something just like that already exists.");
  });

  it("trims the name and description consistently, both in the request and in the returned gallery", async () => {
    authorizedFetch.mockResolvedValue(new Response(NANO, { status: 200 }));
    const result = await uploadNewGallery("  Period 3  ", "demo", false, "  hi  ", "");

    expect((await lastForm()).get("gallery-name")).toBe("Period 3");
    expect((await lastForm()).get("description")).toBe("hi");
    const gallery = result.fold(() => { throw new Error("expected success"); }, (g: Gallery) => g);
    expect(gallery.name).toBe("Period 3");
  });

});
